#include <bits/stdc++.h>
using namespace std;

constexpr long long MOD1=998244353, MOD2=1000000007;

long long counter=0, n_limit, low_sum, total=0, pwr_array[8];
vector<int> num_vectors[7];

void generate_numbers(int depth, int val)
{
    int temp=(counter+MOD1-val)%MOD1;
    num_vectors[depth].push_back(temp);
    low_sum=(low_sum+temp)%MOD2;
    counter++;
    if(depth<6)
    {
        for(int digit=0; digit<10; ++digit)
            generate_numbers(depth+1, val*10+digit);
    }
}

void compute_results(int depth, long long x)
{
    if(x>n_limit) return;
    int i;
    if(x*pwr_array[6]+pwr_array[6]-1<=n_limit && x*pwr_array[7]>n_limit)
    {
        for(i=0;i<=6;i++)
        {
            long long delta=(counter+(MOD1-pwr_array[i])*x)%MOD1;
            total=(total+(delta+MOD2-MOD1)*pwr_array[i]+MOD1*(lower_bound(num_vectors[i].begin(),num_vectors[i].end(),MOD1-delta)-num_vectors[i].begin()))%MOD2;
        }
        total=(total+low_sum)%MOD2;
        counter+=1111111;
        return;
    }
    total=(total+(counter+MOD1-x%MOD1)%MOD1)%MOD2;
    counter++;
    for(i=depth?0:1;i<10;i++) compute_results(depth+1,x*10+i);
}

int main()
{
    int i;
    pwr_array[0]=1;
    for(i=1;i<=7;i++) pwr_array[i]=pwr_array[i-1]*10;
    generate_numbers(0,0);
    for(i=1;i<=6;i++) sort(num_vectors[i].begin(),num_vectors[i].end());
    cin>>n_limit;
    counter=0;
    compute_results(0,0);
    cout<<total<<endl;
    return 0;
}
